function payPanel(){
  const rk=parseRekening(PUB&&PUB.rekening);
  const row=(k,v)=>`<div class="pay-row"><dt>${k}</dt><dd>${v}</dd></div>`;
  let rows=row('Pembayaran melalui','Rekening Bendahara RT03'),info='';
  if(rk&&rk.nomor){
    if(rk.bank)rows+=row('Bank',esc(rk.bank));
    rows+=`<div class="pay-row"><dt id="rekNoL">Nomor rekening</dt><dd><div class="pay-no-row"><span class="pay-no" id="rekNo" aria-labelledby="rekNoL">${esc(rk.nomor)}</span><button type="button" class="btn sec pay-copy" id="rekCopy" aria-label="Salin nomor rekening" data-no="${esc(rk.nomor)}" onclick="copyRekening(this)">${ic('copy')}<span>Salin</span></button></div></dd></div>`;
    if(rk.an)rows+=row('Atas nama',esc(rk.an));
  }else if(rk){
    rows+=row('Rekening',esc(rk.raw));info='<p class="pay-hint">Nomor rekening tidak dapat dibaca otomatis, jadi tombol Salin tidak ditampilkan. Silakan hubungi Bendahara.</p>';
  }else{
    info='<p class="pay-hint">Informasi rekening belum diatur oleh Bendahara. Silakan hubungi Bendahara untuk cara pembayaran.</p>';
  }
  return `<section class="w-card pay" aria-labelledby="payT"><h2 id="payT">${ic('wallet')}Cara Bayar</h2>
    <div class="pay-methods">
      <details class="pay-option"><summary>${ic('bank')}Bank Transfer</summary><div class="pay-option-body">
        <dl class="pay-list">${rows}</dl>${info}
        <p class="pay-fee">Informasi biaya: transfer dari bank yang berbeda dapat dikenakan biaya administrasi sesuai ketentuan bank pengirim.</p>
      </div></details>
      <details class="pay-option"><summary>${ic('qr-code')}QRIS</summary><div class="pay-option-body">
        <p class="pay-hint" style="margin-top:0">Pindai QRIS berikut menggunakan aplikasi pembayaran yang mendukung QRIS.</p>
        <img class="qris-image" src="${QRIS_IMAGE_DATA}" alt="QRIS pembayaran Kas RT 03 Kintamani 24">
        <button type="button" class="btn sec qris-download" onclick="downloadQRIS()">${ic('download')}Download QR Code</button>
        <p class="pay-fee" style="background:var(--ok-soft);color:var(--ok)">Pembayaran melalui QRIS bebas biaya administrasi bagi warga.</p>
      </div></details>
    </div>
    <div class="pay-wa">
      <a class="btn" href="${WA_KONFIRMASI_URL}" target="_blank" rel="noopener noreferrer">${ic('chat')}Konfirmasi Pembayaran</a>
      <a class="btn sec" href="${WA_TANYA_URL}" target="_blank" rel="noopener noreferrer">${ic('chat')}Tanya Bendahara perihal Iuran</a>
    </div>
    <p class="pay-hint">Tombol WhatsApp hanya membuka pesan ke Bendahara. Pembayaran dinyatakan tercatat setelah diverifikasi dan dicatat oleh Bendahara.</p></section>`;
}
