  const mSorted=(p.masuk||[]).slice().sort((a,b)=>String(b.tgl).localeCompare(String(a.tgl))),kSorted=(p.keluar||[]).slice().sort((a,b)=>String(b.tgl).localeCompare(String(a.tgl)));
  const emptyRow=(n,t)=>`<tr class="empty"><td colspan="${n}" data-label="">${t}</td></tr>`;
  const lock=closed?`<div class="alert warn adm" style="margin:14px 0 0">${ic('alert')}Patungan sudah <b>ditutup</b>. Klik <b>Buka kembali</b> bila ingin menambah catatan.</div>`:'';
