function suratFillTemplate(){const k=$('#suratJenis').value,t=suratTemplates[k]||suratTemplates.custom;$('#suratPerihal').value=t.perihal;$('#suratPembuka').value=t.pembuka;$('#suratIsi').value=t.isi;$('#suratPenutup').value=t.penutup;const d=new Date(),y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0');$('#suratTanggal').value=`${y}-${m}-${String(d.getDate()).padStart(2,'0')}`;const code={undangan:'UND',pemberitahuan:'PEM',tinggal:'SKT',custom:'SUR'}[k];$('#suratNomor').value=`RT03/${code}/001/${['','I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'][d.getMonth()+1]}/${y}`;$('#suratLampiran').value='-';$('#suratNama1').value=S.settings.ketua||'';$('#suratNama2').value=S.settings.sekretaris||'';}
