function suratDoc(){const val=id=>$('#'+id).value.trim();const date=val('suratTanggal')?new Date(val('suratTanggal')+'T12:00:00').toLocaleDateString('id-ID',{day:'2-digit',month:'long',year:'numeric'}):'........................';const bodyText=s=>esc(s).replace(/\n/g,'<br>').replace(/\[([^\]]+)\]/g,'<span style="color:#555">[$1]</span>');const logo="data:image/png;base64,";return `<div class="surat-paper"><div class="surat-head"><img src="${logo}" alt="Logo lingkungan"><div><h1>RUKUN TETANGGA 003 RW 024</h1><h1>VILA DAGO CLUSTER KINTAMANI</h1><h2>KELURAHAN BENDA BARU KECAMATAN PAMULANG</h2><h2>KOTA TANGERANG SELATAN</h2></div></div><div class="letter-rule"></div><div class="letter-date">Pamulang, ${date}</div><div class="report-meta"><div><div><b>Nomor</b><span>:</span> ${esc(val('suratNomor'))}</div><div><b>Lampiran</b><span>:</span> ${esc(val('suratLampiran'))||'-'}</div><div><b>Perihal</b><span>:</span> ${esc(val('suratPerihal'))}</div></div><div><b>Kepada Yth.</b><br>${esc(val('suratTujuan'))}<br>${esc(val('suratAlamat')).replace(/\n/g,'<br>')}</div></div><div class="surat-body"><p>${bodyText(val('suratPembuka'))}</p><p>${bodyText(val('suratIsi'))}</p><p>${bodyText(val('suratPenutup'))}</p></div><table class="report-signatures"><tr><td>${esc(val('suratJabatan1'))}<br><br><br><br><b>${esc(val('suratNama1'))||'................................'}</b></td><td>${esc(val('suratJabatan2'))}<br><br><br><br><b>${esc(val('suratNama2'))||'................................'}</b></td></tr></table></div>`}
function suratRender(printNow=false){const html=suratDoc();$('#suratPreviewContent').innerHTML=html;$('#suratPreviewWrap').style.display='block';if(printNow)printHtml('Surat RT 03 — '+$('#suratPerihal').value,html)}
$('#suratJenis').addEventListener('change',suratFillTemplate);$('#suratReset').addEventListener('click',suratFillTemplate);$('#suratPreview').addEventListener('click',()=>suratRender(false));$('#suratPrint').addEventListener('click',()=>suratRender(true));

