function sheetXml(sh){
  let rows='';
  sh.rows.forEach((row,ri)=>{if(!row)return;let cs='';
    row.forEach((c,ci)=>{if(c===null||c===undefined)return;const o=(typeof c==='object')?c:{v:c};const ref=colL(ci)+(ri+1);const s=o.s!==undefined?` s="${o.s}"`:'';
      if(o.f)cs+=`<c r="${ref}"${s}><f>${xe(o.f)}</f>${o.v!==undefined?`<v>${o.v}</v>`:''}</c>`;
      else if(typeof o.v==='number')cs+=`<c r="${ref}"${s}><v>${o.v}</v></c>`;
      else if(o.v===''||o.v===undefined)cs+=`<c r="${ref}"${s}/>`;
      else cs+=`<c r="${ref}"${s} t="inlineStr"><is><t xml:space="preserve">${xe(o.v)}</t></is></c>`});
    rows+=`<row r="${ri+1}"${sh.heights?.[ri]?` ht="${sh.heights[ri]}" customHeight="1"`:''}>${cs}</row>`});
  const cols=sh.cols?`<cols>${sh.cols.map((w,i)=>`<col min="${i+1}" max="${i+1}" width="${w}" customWidth="1"/>`).join('')}</cols>`:'';
  const pane=sh.freeze?`<sheetViews><sheetView workbookViewId="0"><pane ySplit="${sh.freeze}" topLeftCell="A${sh.freeze+1}" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>`:'';
  const merges=sh.merges?.length?`<mergeCells count="${sh.merges.length}">${sh.merges.map(m=>`<mergeCell ref="${m}"/>`).join('')}</mergeCells>`:'';
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheetPr><pageSetUpPr fitToPage="1"/></sheetPr>${pane}<sheetFormatPr defaultRowHeight="15"/>${cols}<sheetData>${rows}</sheetData>${merges}<pageMargins left="0.5" right="0.5" top="0.6" bottom="0.6" header="0.3" footer="0.3"/><pageSetup paperSize="9" orientation="landscape" fitToWidth="1" fitToHeight="0"/></worksheet>`;
}
async function buildXlsx(sheets,filename){
  const z=new JSZip();const n=sheets.length;
  z.file('[Content_Types].xml',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${sheets.map((s,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}<Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/></Types>`);
  z.file('_rels/.rels',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/></Relationships>`);
  z.file('docProps/core.xml',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><dc:title>${xe(filename)}</dc:title><dc:creator>${xe(S.settings.bendahara||'Bendahara RT 03')}</dc:creator><dcterms:created xsi:type="dcterms:W3CDTF">${new Date().toISOString().slice(0,19)}Z</dcterms:created></cp:coreProperties>`);
  z.file('xl/workbook.xml',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheets.map((s,i)=>`<sheet name="${xe(s.name.replace(/[\[\]\*\?\/\\:]/g,'-').slice(0,31))}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets><calcPr calcId="191029" fullCalcOnLoad="1"/></workbook>`);
  z.file('xl/_rels/workbook.xml.rels',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map((s,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}<Relationship Id="rId${n+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`);
  z.file('xl/styles.xml',STYLES);
  sheets.forEach((s,i)=>z.file(`xl/worksheets/sheet${i+1}.xml`,sheetXml(s)));
  const blob=await z.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',compression:'DEFLATE'});
  download(blob,filename);
}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1500)}
const H_=v=>({v,s:2}),T_=v=>({v,s:3}),M_=v=>({v:+v||0,s:4}),C_=v=>({v,s:11});
function sheetMasuk(list,title){
  const rows=[[{v:title,s:1}],[{v:S.settings.nama,s:7}],[],[H_('No'),H_('Tanggal'),H_('Blok'),H_('Nama Warga'),H_('Kategori'),H_('Metode'),H_('Keterangan'),H_('Jumlah')]];
  list.forEach((t,i)=>{const h=houseById(t.houseId);rows.push([C_(i+1),T_(fmtTgl(t.tgl)),T_(h?.blok||'-'),T_(h?.nama||'-'),T_(t.kategori),T_(t.metode||''),T_(t.ket||''),M_(t.jumlah)])});
  const e=rows.length;rows.push([{v:'TOTAL KAS MASUK',s:5},{v:'',s:5},{v:'',s:5},{v:'',s:5},{v:'',s:5},{v:'',s:5},{v:'',s:5},{f:list.length?`SUM(H5:H${e})`:'0',v:list.reduce((a,t)=>a+ +t.jumlah,0),s:6}]);
  return {name:'Kas Masuk',rows,cols:[5,14,9,30,18,10,34,16],freeze:4,merges:[`A${e+1}:G${e+1}`]};
}
function sheetKeluar(list,title){
  const rows=[[{v:title,s:1}],[{v:S.settings.nama,s:7}],[],[H_('No'),H_('Tanggal'),H_('Kategori'),H_('Uraian / Detail'),H_('Dibayar ke'),H_('Metode'),H_('No. Nota / Ket.'),H_('Jumlah')]];
  list.forEach((t,i)=>rows.push([C_(i+1),T_(fmtTgl(t.tgl)),T_(t.kategori),T_(t.uraian),T_(t.penerima||''),T_(t.metode||''),T_(t.ket||''),M_(t.jumlah)]));
  const e=rows.length;rows.push([{v:'TOTAL KAS KELUAR',s:5},{v:'',s:5},{v:'',s:5},{v:'',s:5},{v:'',s:5},{v:'',s:5},{v:'',s:5},{f:list.length?`SUM(H5:H${e})`:'0',v:list.reduce((a,t)=>a+ +t.jumlah,0),s:6}]);
  return {name:'Kas Keluar',rows,cols:[5,14,22,36,22,10,26,16],freeze:4,merges:[`A${e+1}:G${e+1}`]};
}
function sheetStatus(y,m,name){
  const rows=[[{v:`STATUS IURAN WARGA s.d. ${BULAN[m].toUpperCase()} ${y}`,s:1}],[{v:'Lunas s.d. dihitung dari total bayar ÷ tarif; tunggakan = tarif × jumlah bulan berjalan − total bayar',s:7}],[],
   [H_('No'),H_('Blok'),H_('Nama Warga'),H_('Tarif/Bulan'),H_(`Bayar ${BLN[m]}`),H_(`Total Bayar s.d. ${BLN[m]}`),H_('Lunas s.d.'),H_('Bulan Tunggak'),H_('Tunggakan'),H_('Status')]];
  S.houses.forEach((h,i)=>{const s=iuranHouse(h,y,m);rows.push([C_(i+1),T_(h.blok),T_(h.nama),M_(h.tarif),M_(s.grid[m]),M_(s.totalUpto),T_(s.lunasSd),C_(s.blnTunggak||'-'),{v:s.tunggakan,s:s.tunggakan?10:4},T_(s.label)])});
  const e=rows.length;rows.push([{v:'TOTAL',s:5},{v:'',s:5},{v:'',s:5},{v:'',s:5},{f:`SUM(E5:E${e})`,s:6},{f:`SUM(F5:F${e})`,s:6},{v:'',s:5},{v:'',s:5},{f:`SUM(I5:I${e})`,s:6},{v:'',s:5}]);
  return {name:name||'Status Iuran',rows,cols:[5,9,32,14,14,18,14,13,15,22],freeze:4};
}
$('#lpExpBln').onclick=async()=>{
  const y=Y(),m=+$('#lpBln').value,d=dataBulan(y,m),P=`${BULAN[m]} ${y}`;
  const R=[[{v:`LAPORAN KAS ${S.settings.nama.toUpperCase()}`,s:1}],[{v:`Periode: ${P} · Dibuat: ${new Date().toLocaleString('id-ID')} · Bendahara: ${S.settings.bendahara||'-'}`,s:7}],[],
   [H_('Uraian'),H_('Jumlah')],[T_(`Saldo Awal 1 ${P}`),M_(d.r.awal)],[T_('(+) Total Kas Masuk'),{v:d.r.masuk,s:12}],[T_('(−) Total Kas Keluar'),{v:d.r.keluar,s:10}],
   [{v:`SALDO AKHIR ${P.toUpperCase()}`,s:5},{f:'B5+B6-B7',v:d.r.akhir,s:6}],[],
   [{v:'RINCIAN KAS MASUK PER KATEGORI',s:8}],[H_('Kategori'),H_('Jumlah')]];
  Object.entries(d.katIn).forEach(([k,v])=>R.push([T_(k),M_(v)]));
  R.push([T_('Jumlah rumah yang membayar bulan ini'),C_(d.nRumah+' rumah')]);R.push([]);
  R.push([{v:'RINCIAN KAS KELUAR PER KATEGORI',s:8}],[H_('Kategori'),H_('Jumlah')]);
  Object.entries(d.katOut).sort((a,b)=>b[1]-a[1]).forEach(([k,v])=>R.push([T_(k),M_(v)]));
  R.push([]);R.push([{v:'DETAIL PENGELUARAN',s:8}],[H_('Uraian'),H_('Jumlah')]);
  d.ko.forEach(t=>R.push([T_(`${fmtTgl(t.tgl)} · ${t.uraian}${t.penerima?' (ke '+t.penerima+')':''}`),M_(t.jumlah)]));
  R.push([]);R.push([{v:'Mengetahui, Ketua RT 03',s:8},{v:'Bendahara RT 03',s:8}],[],[],[{v:S.settings.ketua||'(....................)'},{v:S.settings.bendahara||'(....................)'}]);
  await buildXlsx([{name:'Ringkasan',rows:R,cols:[58,22]},sheetMasuk(d.mi,`KAS MASUK — ${P.toUpperCase()}`),sheetKeluar(d.ko,`KAS KELUAR — ${P.toUpperCase()}`),sheetStatus(y,m)],`Laporan Kas RT03 - ${y}-${String(m+1).padStart(2,'0')} ${BULAN[m]}.xlsx`);
  toast('📥 Laporan '+P+' diexport ke Excel')};
$('#lpExpThn').onclick=async()=>{
  const y=Y(),r=rekapTahun(y);
  const R=[[{v:`REKAP UANG KAS ${S.settings.nama.toUpperCase()} — TAHUN ${y}`,s:1}],[{v:`Dibuat: ${new Date().toLocaleString('id-ID')}`,s:7}],[],
   [H_('Bulan'),H_('Saldo Awal'),H_('Kas Masuk'),H_('Kas Keluar'),H_('Saldo Akhir'),H_('Status'),H_('Rincian Pengeluaran')]];
  r.forEach((x,i)=>{const rr=5+i;R.push([T_(BULAN[i]),i===0?M_(x.awal):{f:`E${rr-1}`,v:x.awal,s:4},M_(x.masuk),M_(x.keluar),{f:`B${rr}+C${rr}-D${rr}`,v:x.akhir,s:4},T_(x.keluar>x.masuk?'Kas keluar > masuk':'Aman'),
    T_(S.keluar.filter(t=>yOf(t.tgl)===y&&mOf(t.tgl)===i).map(t=>`${t.uraian} - ${num(t.jumlah)}`).join('\n'))])});
  R.push([{v:`TOTAL ${y}`,s:5},{f:'B5',v:r[0].awal,s:6},{f:'SUM(C5:C16)',v:r.reduce((a,x)=>a+x.masuk,0),s:6},{f:'SUM(D5:D16)',v:r.reduce((a,x)=>a+x.keluar,0),s:6},{f:'E16',v:r[11].akhir,s:6},{v:'Saldo akhir tahun',s:5},{v:'',s:5}]);
  // grid iuran
  const G=[[{v:`REKAP IURAN WARGA — TAHUN ${y}`,s:1}],[{v:'Nominal yang diterima per bulan (basis kas)',s:7}],[],[H_('No'),H_('Blok'),H_('Nama Warga'),H_('Tarif/Bulan'),...BLN.map(H_),H_('Total Dibayar'),H_('Kekurangan s.d. Des'),H_('Lunas s.d.'),H_('Status')]];
  const cm=Math.max(0,bulanBerjalan(y));
  S.houses.forEach((h,i)=>{const s=iuranHouse(h,y,cm),rr=5+i;G.push([C_(i+1),T_(h.blok),T_(h.nama),M_(h.tarif),...s.grid.map(v=>v?{v,s:12}:{v:'',s:4}),{f:`SUM(E${rr}:P${rr})`,v:s.totalAll,s:4},{f:`MAX(0,D${rr}*12-Q${rr})`,v:s.sisaSetahun,s:4},T_(s.lunasSd),T_(s.label)])});
  const ge=G.length;G.push([{v:'TOTAL',s:5},{v:'',s:5},{v:'',s:5},{v:'',s:5},...BLN.map((b,i)=>({f:`SUM(${colL(4+i)}5:${colL(4+i)}${ge})`,s:6})),{f:`SUM(Q5:Q${ge})`,s:6},{f:`SUM(R5:R${ge})`,s:6},{v:'',s:5},{v:'',s:5}]);
  // kategori x bulan
  const kats=[...new Set(S.keluar.filter(t=>yOf(t.tgl)===y).map(t=>t.kategori))];
  const K=[[{v:`PENGELUARAN PER KATEGORI PER BULAN — ${y}`,s:1}],[],[H_('Kategori'),...BLN.map(H_),H_('Total')]];
  kats.forEach((k,i)=>{const rr=4+i;K.push([T_(k),...BLN.map((b,m)=>M_(S.keluar.filter(t=>yOf(t.tgl)===y&&mOf(t.tgl)===m&&t.kategori===k).reduce((a,t)=>a+ +t.jumlah,0))),{f:`SUM(B${rr}:M${rr})`,s:6}])});
  const ke=K.length;K.push([{v:'TOTAL',s:5},...BLN.map((b,i)=>({f:`SUM(${colL(1+i)}4:${colL(1+i)}${ke})`,s:6})),{f:`SUM(N4:N${ke})`,s:6}]);
  const allIn=S.masuk.filter(t=>yOf(t.tgl)===y).sort((a,b)=>a.tgl.localeCompare(b.tgl)),allOut=S.keluar.filter(t=>yOf(t.tgl)===y).sort((a,b)=>a.tgl.localeCompare(b.tgl));
  await buildXlsx([{name:`Rekap Kas ${y}`,rows:R,cols:[14,17,17,17,17,18,44],freeze:4},{name:`Rekap Iuran ${y}`,rows:G,cols:[5,9,30,13,...BLN.map(()=>11),15,17,12,22],freeze:4},
    {name:'Pengeluaran per Kategori',rows:K,cols:[26,...BLN.map(()=>13),16],freeze:3},sheetMasuk(allIn,`SEMUA KAS MASUK ${y}`),sheetKeluar(allOut,`SEMUA KAS KELUAR ${y}`)],`Laporan Kas RT03 - Tahun ${y}.xlsx`);
  toast('📥 Laporan tahunan '+y+' diexport ke Excel')};
