function rSetting(){const st=S.settings;$('#stNama').value=st.nama||'';$('#stKetua').value=st.ketua||'';$('#stBend').value=st.bendahara||'';$('#stRek').value=st.rekening||'';$('#stWaKetua').value=st.waKetua||'';$('#stWa').value=st.waBendahara||'';
  $('#stYearLbl').textContent=Y();const sa=st.saldoAwal?.[Y()];$('#stSaldo').value=(sa!==undefined&&sa!==null&&sa!=='')?num(sa):'';
  $('#stSaldo').placeholder='otomatis: '+num(saldoAwalTahun(Y()));
  $('#stRutin').value=(st.rutin||[]).map(r=>r.join(' | ')).join('\n');
  document.querySelectorAll('#p-setting input,#p-setting textarea').forEach(e=>e.disabled=ROLE!=='admin');$('#bkInfo').innerHTML=`Isi data: ${S.houses.length} rumah · ${S.masuk.length} transaksi masuk · ${S.keluar.length} transaksi keluar · ${(S.patungan||[]).length} patungan`}
$('#stSave').onclick=()=>{const st=S.settings;st.nama=$('#stNama').value.trim()||st.nama;st.ketua=$('#stKetua').value.trim();st.bendahara=$('#stBend').value.trim();st.rekening=$('#stRek').value.trim();st.waKetua=$('#stWaKetua').value.trim();st.waBendahara=$('#stWa').value.trim();
  st.saldoAwal=st.saldoAwal||{};if($('#stSaldo').value.trim()==='')delete st.saldoAwal[Y()];else st.saldoAwal[Y()]=parseNum($('#stSaldo').value);
  st.rutin=$('#stRutin').value.split('\n').map(l=>l.split('|').map(x=>x.trim())).filter(a=>a[0]).map(a=>[a[0],a[1]||'Lain-lain',parseNum(a[2])]);
  logAct('Ubah pengaturan');_saveMsg='Pengaturan';save();toast('⏳ Pengaturan dicatat, menyimpan ke server…')};
function doBackup(){if(ROLE==='admin'){S.meta.lastBackup=new Date().toISOString();save()}
  download(new Blob([JSON.stringify(S,null,1)],{type:'application/json'}),`Backup Kas RT03 ${todayStr()}.json`);renderAll();toast('🛟 Backup diunduh, simpan ke OneDrive ya')}
$('#bkSave').onclick=doBackup;$('#bkLoad').onclick=()=>$('#bkFile').click();
$('#bkFile').onchange=e=>{const f=e.target.files[0];if(!f)return;const rd=new FileReader();rd.onload=()=>{try{const d=JSON.parse(rd.result);if(!d.houses||!d.masuk||!d.keluar)throw 0;
  if(confirm(`Restore backup ini? (${d.houses.length} rumah, ${d.masuk.length} masuk, ${d.keluar.length} keluar). Data saat ini akan diganti.`)){const _pt=S.patungan;S=d;S.meta=S.meta||{};if(!Array.isArray(S.patungan))S.patungan=Array.isArray(_pt)?_pt:[];logAct('Restore data dari file backup');_saveMsg='Restore backup';save();toast('⏳ Backup di-restore, menyimpan ke server…')}}catch(x){alert('File backup tidak valid')}};rd.readAsText(f);e.target.value=''};
$('#rsAll').onclick=()=>{if(confirm('Hapus SEMUA transaksi masuk & keluar Kas RT? Data rumah dan catatan Patungan tetap. (backup dulu!)')&&confirm('Yakin? Tindakan ini tidak bisa dibatalkan.')){logAct('Kosongkan semua transaksi');S.masuk=[];S.keluar=[];S.meta.seeded=false;save();toast('🗑️ Semua transaksi dihapus')}};
/* ---------- IMPORT EXCEL ---------- */
$('#imBtn').onclick=()=>$('#imFile').click();
$('#imFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;
  try{const wb=await readXlsx(f);const res=parseIuranWorkbook(wb);showImportPreview(res)}catch(err){console.error(err);alert('Gagal membaca Excel: '+err.message)}};
async function readXlsx(file){
  const z=await JSZip.loadAsync(file);const P=s=>new DOMParser().parseFromString(s,'application/xml');
  const tags=(n,t)=>[...n.getElementsByTagNameNS('*',t)];
  const ss=[];const ssf=z.file('xl/sharedStrings.xml');if(ssf){tags(P(await ssf.async('string')),'si').forEach(si=>{ss.push(tags(si,'t').filter(t=>t.parentNode.localName!=='rPh').map(t=>t.textContent).join(''))})}
  const wbx=P(await z.file('xl/workbook.xml').async('string'));const rels=P(await z.file('xl/_rels/workbook.xml.rels').async('string'));
  const rmap={};tags(rels,'Relationship').forEach(r=>rmap[r.getAttribute('Id')]=r.getAttribute('Target'));
  const out=[];
  for(const s of tags(wbx,'sheet')){
    const rid=s.getAttribute('r:id')||s.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id');
    let tg=rmap[rid];if(!tg)continue;tg=tg.replace(/^\/?xl\//,'').replace(/^\//,'');const fx=z.file('xl/'+tg);if(!fx)continue;
    const doc=P(await fx.async('string'));const grid=[];
    tags(doc,'c').forEach(c=>{const ref=c.getAttribute('r');const m=ref.match(/^([A-Z]+)(\d+)$/);if(!m)return;
      let col=0;for(const ch of m[1])col=col*26+ch.charCodeAt(0)-64;col--;const row=+m[2]-1;
      const t=c.getAttribute('t');const vEl=tags(c,'v')[0];let v=null;
      if(t==='s')v=ss[+vEl?.textContent];else if(t==='inlineStr')v=tags(c,'t').map(x=>x.textContent).join('');else if(t==='str'||t==='e')v=vEl?.textContent??null;else if(t==='b')v=vEl?+vEl.textContent:null;else if(vEl)v=+vEl.textContent;
      (grid[row]=grid[row]||[])[col]=v});
    out.push({name:s.getAttribute('name'),grid});
  }
  return out;
}
function parseIuranWorkbook(wb){
  const norm=v=>String(v??'').toLowerCase().replace(/\s+/g,' ').trim();
  const res={houses:[],masuk:[],keluar:[],saldoAwal:null,year:null,notes:[],kasMasukExcel:Array(12).fill(null),kasKeluarExcel:Array(12).fill(null)};
  // ---- Rekap Iuran
  let shI=null,hr=-1,cB,cN,cT,cM=[];
  for(const sh of wb){for(let r=0;r<Math.min(sh.grid.length,40);r++){const row=sh.grid[r]||[];const ib=row.findIndex(v=>/^blok/.test(norm(v)));const it=row.findIndex(v=>/^tarif/.test(norm(v)));
      if(ib>=0&&it>=0){shI=sh;hr=r;cB=ib;cT=it;cN=row.findIndex(v=>/nama/.test(norm(v)));
        const keys=['jan','feb','mar','apr','mei','jun','jul','agu','sep','okt','nov','des'];cM=keys.map(k=>row.findIndex(v=>norm(v).startsWith(k)||(k==='agu'&&norm(v).startsWith('ags'))));break}}if(shI)break}
  if(!shI)throw new Error('Sheet Rekap Iuran (kolom "Blok" & "Tarif") tidak ditemukan');
  for(let r=0;r<hr;r++){(shI.grid[r]||[]).forEach(v=>{const m=String(v??'').match(/(20\d\d)/);if(m&&!res.year)res.year=+m[1]})}
  if(!res.year)res.year=Y();
  if(cM.some(x=>x<0))res.notes.push('⚠️ Sebagian kolom bulan tidak terdeteksi: '+cM.map((x,i)=>x<0?BLN[i]:null).filter(Boolean).join(', '));
  for(let r=hr+1;r<shI.grid.length;r++){const row=shI.grid[r]||[];const b=String(row[cB]??'').trim();if(!b||!/^[A-Za-z]+\s*\d/.test(b))continue;
    const id='h'+String(res.houses.length+1).padStart(2,'0');const nama=String(row[cN]??'').trim()||'-';
    res.houses.push({id,blok:b,nama,tarif:+row[cT]||0,hp:'',status:/kosong/i.test(nama)?'Kosong':/kontrak/i.test(nama)?'Kontrak':'Dihuni',ket:''});
    cM.forEach((c,m)=>{if(c<0)return;const v=+row[c]||0;if(v>0)res.masuk.push({id:uid('m'),tgl:`${res.year}-${String(m+1).padStart(2,'0')}-10`,houseId:id,kategori:'Iuran Warga',jumlah:v,metode:'Transfer',ket:'Import Excel'})})}
  // ---- Rekap Kas
  let shK=null,kr=-1,cBul,cRem,cIn,cOut;
  for(const sh of wb){for(let r=0;r<Math.min(sh.grid.length,40);r++){const row=sh.grid[r]||[];const ib=row.findIndex(v=>norm(v)==='bulan');const io=row.findIndex(v=>/kas keluar/.test(norm(v)));
      if(ib>=0&&io>=0){shK=sh;kr=r;cBul=ib;cOut=io;cIn=row.findIndex(v=>/kas masuk/.test(norm(v)));cRem=row.findIndex(v=>/remark|keterangan|rincian/.test(norm(v)));break}}if(shK)break}
  if(shK){
    for(let r=0;r<kr;r++){const row=shK.grid[r]||[];row.forEach((v,c)=>{if(/kas awal|saldo awal/.test(norm(v))&&res.saldoAwal===null){
      for(let cc=c+1;cc<row.length;cc++)if(typeof row[cc]==='number'){res.saldoAwal=row[cc];break}
      if(res.saldoAwal===null)for(let rr=r+1;rr<=r+2;rr++){const v2=(shK.grid[rr]||[])[c];if(typeof v2==='number'){res.saldoAwal=v2;break}}}})}
    let cur=-1;const remByM=Array.from({length:12},()=>[]);
    for(let r=kr+1;r<shK.grid.length;r++){const row=shK.grid[r]||[];const bl=norm(row[cBul]);if(/^total/.test(bl))break;
      const mi=BULAN.findIndex(b=>bl.startsWith(b.toLowerCase()));if(mi>=0){cur=mi;if(typeof row[cOut]==='number')res.kasKeluarExcel[mi]=row[cOut];if(cIn>=0&&typeof row[cIn]==='number')res.kasMasukExcel[mi]=row[cIn]}
      if(cur>=0&&cRem>=0&&row[cRem]!=null)String(row[cRem]).split(/\r?\n/).forEach(l=>{if(l.trim())remByM[cur].push(l.trim())})}
    remByM.forEach((lines,m)=>{let sum=0;
      lines.forEach(l=>{const mm=l.match(/^(.*?)[\s\-–:=]*(?:rp\.?\s*)?(\d[\d.,]*)\s*$/i);if(!mm){res.notes.push(`⚠️ ${BULAN[m]}: baris remarks tidak terbaca → "${l}"`);return}
        const j=parseNum(mm[2].replace(/[.,]\d{1,2}$/,''));const ur=mm[1].trim()||'Pengeluaran';sum+=j;
        res.keluar.push({id:uid('k'),tgl:`${res.year}-${String(m+1).padStart(2,'0')}-28`,kategori:guessKat(ur),uraian:ur,jumlah:j,penerima:'',metode:'Tunai',ket:'Import Excel'})});
      const ex=res.kasKeluarExcel[m];
      if(ex!=null&&ex!==sum){const d=ex-sum;res.notes.push(`⚠️ ${BULAN[m]}: total Remarks ${num(sum)} ≠ Kas Keluar ${num(ex)} → ditambahkan baris selisih ${num(d)} (mohon dicek)`);
        if(d>0)res.keluar.push({id:uid('k'),tgl:`${res.year}-${String(m+1).padStart(2,'0')}-28`,kategori:'Lain-lain',uraian:'Selisih import (mohon dirinci)',jumlah:d,penerima:'',metode:'Tunai',ket:'Import Excel - selisih'})}});
  }else res.notes.push('⚠️ Sheet Rekap Kas (kolom "Bulan" & "Kas Keluar") tidak ditemukan — pengeluaran & saldo awal tidak diimport');
  // compare masuk
  const mIn=Array(12).fill(0);res.masuk.forEach(t=>mIn[mOf(t.tgl)]+=t.jumlah);
  res.kasMasukExcel.forEach((v,m)=>{if(v!=null&&v!==mIn[m])res.notes.push(`⚠️ ${BULAN[m]}: total iuran per rumah ${num(mIn[m])} ≠ Kas Masuk di sheet rekap ${num(v)}`)});
  return res;
}
function guessKat(u){u=u.toLowerCase();
  if(/iuran rw/.test(u))return 'Iuran RW';if(/sampah|kebersihan/.test(u))return 'Kebersihan & Sampah';if(/listrik|air|pln/.test(u))return 'Utilitas (Listrik/Air)';
  if(/security|satpam|keamanan|ronda/.test(u))return 'Keamanan';if(/rumput|lampu|karpet|perbaikan|cat|pos/.test(u))return 'Fasilitas & Perawatan';
  if(/bukber|halal|17|agustus|lomba|acara|kegiatan/.test(u))return 'Kegiatan Warga';if(/posyandu|duka|sakit|santunan|sosial/.test(u))return 'Sosial & Kesehatan';return 'Lain-lain'}
let PENDING=null;
function showImportPreview(res){PENDING=res;
  const tin=res.masuk.reduce((a,t)=>a+t.jumlah,0),tout=res.keluar.reduce((a,t)=>a+t.jumlah,0);
  modal(`<h3>📂 Pratinjau Import Excel — Tahun ${res.year}</h3>
   <div class="sum-line"><span>Jumlah rumah</span><b>${res.houses.length}</b></div>
   <div class="sum-line"><span>Transaksi iuran (per rumah per bulan)</span><b>${res.masuk.length} · ${rp(tin)}</b></div>
   <div class="sum-line"><span>Rincian pengeluaran</span><b>${res.keluar.length} · ${rp(tout)}</b></div>
   <div class="sum-line"><span>Saldo awal 1 Januari</span><b>${res.saldoAwal!=null?rp(res.saldoAwal):'tidak ditemukan'}</b></div>
   <div class="sum-line total"><span>Saldo akhir hasil hitung</span><span>${rp((res.saldoAwal||0)+tin-tout)}</span></div>
   ${res.notes.length?`<div class="alert warn" style="margin-top:12px">${res.notes.map(esc).join('<br>')}</div>`:'<div class="alert ok" style="margin-top:12px">✅ Semua total per bulan cocok dengan sheet rekap.</div>'}
   <div class="info small">Data rumah akan diganti dengan isi Excel (No. HP yang sudah diisi dipertahankan bila blok sama). Transaksi tahun ${res.year} diganti; tahun lain tidak terpengaruh.</div>
   <div class="btn-row"><button class="btn ok" onclick="applyImport()">✅ Terapkan Import</button><button class="btn ghost" onclick="closeModal()">Batal</button></div>`)}
function applyImport(){const r=PENDING;if(!r)return;const y=r.year;
  const old={};S.houses.forEach(h=>old[h.blok]=h);
  r.houses.forEach(h=>{const o=old[h.blok];if(o){h.hp=o.hp||'';h.ket=o.ket||'';if(o.akun)h.akun=o.akun;h.akunDibuat=o.akunDibuat}});
  // remap old non-iuran / other-year masuk to new ids by blok
  const idMap={};S.houses.forEach(h=>{const n=r.houses.find(x=>x.blok===h.blok);if(n)idMap[h.id]=n.id});
  const keepIn=S.masuk.filter(t=>yOf(t.tgl)!==y).map(t=>({...t,houseId:t.houseId?(idMap[t.houseId]||null):null}));
  S.houses=r.houses;S.masuk=[...keepIn,...r.masuk];S.keluar=[...S.keluar.filter(t=>yOf(t.tgl)!==y),...r.keluar];
  if(r.saldoAwal!=null)S.settings.saldoAwal[y]=r.saldoAwal;S.settings.tahun=y;S.meta.seeded=false;logAct('Import Excel tahun '+y);closeModal();_saveMsg='Import Excel';save();toast('⏳ Import diterapkan, menyimpan ke server…')}
/* ---------- ADMIN: TAMPILAN LOGIN (pengingat + tema latar) ---------- */
/* Semua penulisan dilindungi RLS server (public.my_role()='admin'); cek ROLE di klien hanya untuk UX. */
const LCA={loaded:false,loading:false,themes:[],reminder:null,showArchived:false,remTouched:false,err:''};
function lcDeny(){toast('⚠️ Hanya Admin yang dapat mengubah tampilan login');return false}
async function lcLoad(force){
  if(LCA.loading||(LCA.loaded&&!force))return;LCA.loading=true;LCA.err='';
  try{
    const [t,r]=await Promise.all([
      sb.from('kas_login_theme').select(LG_THEME_COLS).order('created_at',{ascending:false}),
      sb.from('kas_login_reminder').select(LG_REM_COLS).eq('id',1).maybeSingle()]);
    if(t.error)throw t.error;if(r.error)throw r.error;
    LCA.themes=(t.data||[]).map(lgThemeFromRow);LCA.reminder=lgRemFromRow(r.data);LCA.loaded=true;
    LG.themes=LCA.themes.filter(x=>x.status!=='archived');LG.reminder=LCA.reminder;
  }catch(e){console.error(e);LCA.err=e.message||String(e)}
  LCA.loading=false;if(PAGE==='tampilan')rTampilan();
}
function rTampilan(){
  if(ROLE!=='admin')return;
  if(!LCA.loaded&&!LCA.err){$('#lcThemes').innerHTML='<p class="muted">Memuat…</p>';lcLoad();return}
  if(LCA.err){$('#lcThemes').innerHTML=`<div class="alert bad">${ic('alert')}Gagal memuat konfigurasi login: ${esc(LCA.err)}<br>Pastikan <b>migrations/2026-10-19_login_theme_reminder.sql</b> sudah dijalankan di Supabase SQL Editor.</div><button class="btn sec sm" type="button" onclick="LCA.err='';lcLoad(true)">Coba lagi</button>`;return}
  lcFillReminder();lcRenderThemes();
}
/* ===== Pengingat ===== */
function lcFillReminder(){
  if(LCA.remTouched)return lcPreviewReminder();
  const r=LCA.reminder||{enabled:false,title:'Pengingat',message:''};
  $('#remOn').checked=!!r.enabled;$('#remTitle').value=r.title||'';$('#remMsg').value=r.message||'';
  $('#remStart').value=LoginCore.isoToWibLocal(r.startsAt);$('#remEnd').value=LoginCore.isoToWibLocal(r.endsAt);
  $('#remMeta').textContent=r.updatedAt?('Terakhir diubah '+fmtWaktu(r.updatedAt)+(r.updatedBy?' oleh '+r.updatedBy:'')):'';
  lcPreviewReminder();
}
function lcReadReminder(){return {enabled:$('#remOn').checked,title:$('#remTitle').value,message:$('#remMsg').value,
  startsAt:$('#remStart').value?LoginCore.wibLocalToIso($('#remStart').value)||'invalid':null,endsAt:$('#remEnd').value?LoginCore.wibLocalToIso($('#remEnd').value)||'invalid':null}}
function lcPreviewReminder(){
  const v=lcReadReminder();$('#remCount').textContent=LoginCore.cleanText(v.message).length;
  const pv=$('#remPrev');pv.textContent='';
  const r={enabled:v.enabled,title:v.title,message:v.message};
  if(!LoginCore.reminderVisible(r,new Date())){const p=document.createElement('div');p.className='lc-prev-empty';
    p.textContent=v.enabled?'Pesan kosong — pengingat tidak akan tampil.':'Pengingat dinonaktifkan — tidak tampil di halaman login.';pv.appendChild(p);return}
  const card=document.createElement('div');card.className='auth-remind keep-emoji';
  card.innerHTML=`<span class="ar-ic" aria-hidden="true">${ic('bell')}</span><div class="ar-body"><p class="ar-t"></p><p class="ar-m"></p></div>`;
  card.querySelector('.ar-t').textContent=LoginCore.reminderTitle(r);card.querySelector('.ar-m').textContent=LoginCore.cleanText(r.message,LoginCore.REM_LIMITS.message);
  pv.appendChild(card);
}
['remOn','remTitle','remMsg','remStart','remEnd'].forEach(id=>{const el=document.getElementById(id);
  el.addEventListener('input',()=>{LCA.remTouched=true;lcPreviewReminder()});el.addEventListener('change',()=>{LCA.remTouched=true;lcPreviewReminder()})});
$('#remReset').onclick=()=>{LCA.remTouched=false;clearErrs($('#remCard'));lcFillReminder()};
$('#remSave').onclick=async()=>{
  if(ROLE!=='admin')return lcDeny();
  clearErrs($('#remCard'));
  const v=LoginCore.validateReminder(lcReadReminder());
  if(!v.ok){const map={title:'remTitle',message:'remMsg',startsAt:'remStart',endsAt:'remEnd'};const k=Object.keys(v.errors)[0];return invalid(map[k],v.errors[k])}
  if(lockSubmit('remSave',['remSave'],1500))return;
  const row={enabled:v.value.enabled,title:v.value.title||'Pengingat',message:v.value.message,starts_at:v.value.startsAt,ends_at:v.value.endsAt};
  const {data,error}=await sb.from('kas_login_reminder').update(row).eq('id',1).select(LG_REM_COLS).maybeSingle();
  if(error)return toast('❌ Gagal simpan pengingat: '+error.message);
  if(!data)return toast('❌ Pengingat tidak tersimpan (akses ditolak server atau baris belum dibuat — jalankan migrasi SQL)');
  LCA.reminder=lgRemFromRow(data);LG.reminder=LCA.reminder;LCA.remTouched=false;lcFillReminder();
  logAct('Ubah pengingat login: '+(row.enabled?'tampil':'nonaktif')+' · "'+row.title+'"');_saveMsg='Pengingat login';save();
  toast('✅ Pengingat login disimpan — langsung berlaku tanpa deploy');
};
/* ===== Tema ===== */
const lcSched=t=>(t.startsAt||t.endsAt)?`${t.startsAt?fmtWaktu(t.startsAt):'kapan saja'} – ${t.endsAt?fmtWaktu(t.endsAt):'tanpa batas'} WIB`:'Tanpa jadwal';
function lcStatusBadge(t){const l=LoginCore.themeStatusLabel(t);const c=t.status==='active'?'b-ok':t.status==='archived'?'b-mute':!LoginCore.isComplete(t)?'b-warn':'b-mute';
  return `<span class="badge ${c}">${esc(l)}</span>`}
function lcThumbs(t){return `<div class="th-thumbs">${LoginCore.VARIANTS.map(v=>`<figure class="th-thumb">${t.assets[v]?`<img src="${esc(t.assets[v])}" alt="${esc(LoginCore.VARIANT_LABEL[v])}" loading="lazy">`:`<span class="ph">Belum ada</span>`}<figcaption>${esc(LoginCore.VARIANT_LABEL[v])}</figcaption></figure>`).join('')}</div>`}
function lcRenderThemes(){
  const now=new Date(),bucket=LoginCore.timeBucket(now);
  const res=LoginCore.resolveTheme(LCA.themes.filter(t=>t.status!=='archived'),now,LOGIN_BUILTIN);
  const cur=LoginCore.pickAsset(res.theme,bucket,LOGIN_BUILTIN);
  const srcL={event:'tema acara aktif',default:'tema default',builtin:'tema bawaan (fallback)'}[res.source];
  let h=`<div class="th-now"><img src="${esc(cur)}" alt=""><div><b>Sekarang tampil:</b> ${esc(res.theme.name)} <span class="muted small">(${srcL})</span><br><span class="muted small">Latar ${esc(LoginCore.VARIANT_LABEL[bucket])} · ${esc(LoginCore.VARIANT_HOURS[bucket])} WIB</span></div></div>`;
  const list=LCA.themes.filter(t=>LCA.showArchived||t.status!=='archived');
  const hasDef=LCA.themes.some(t=>t.isDefault&&t.status!=='archived');
  h+=`<div class="th-item"><div class="th-head"><div><b>${esc(LOGIN_BUILTIN.name)}</b><div class="th-badges"><span class="badge b-mute">Bawaan</span>${hasDef?'':'<span class="badge b-pri">Default saat ini</span>'}</div></div></div>${lcThumbs(LOGIN_BUILTIN)}<div class="th-meta">Dipakai otomatis bila tidak ada tema acara aktif dan tidak ada tema default.${hasDef?` <button type="button" class="linkbtn" onclick="lcSetDefault(null)">Jadikan default</button>`:''}</div></div>`;
  h+=list.map(t=>{const comp=LoginCore.isComplete(t),arch=t.status==='archived';
    return `<div class="th-item${arch?' archived':''}"><div class="th-head"><div><b>${esc(t.name)}</b><div class="th-badges">${lcStatusBadge(t)}${t.isDefault?'<span class="badge b-pri">Default</span>':''}${res.theme&&res.theme.id===t.id?'<span class="badge b-ok">Sedang tampil</span>':''}</div></div></div>
    ${lcThumbs(t)}<div class="th-meta">Prioritas ${t.priority} · ${esc(lcSched(t))}${t.updatedAt?' · diubah '+esc(fmtWaktu(t.updatedAt)):''}</div>
    <div class="th-actions">${arch?`<button type="button" class="btn sec sm" onclick="lcSetStatus('${t.id}','${comp?'inactive':'draft'}')">Pulihkan dari arsip</button>`:`
      <button type="button" class="btn sec sm" onclick="lcEdit('${t.id}')">${ic('pencil')}Edit</button>
      <button type="button" class="btn sec sm" onclick="lcPreview('${t.id}')">${ic('eye')}Pratinjau</button>
      ${t.status==='active'?`<button type="button" class="btn sec sm" onclick="lcSetStatus('${t.id}','inactive')">Nonaktifkan</button>`
        :`<button type="button" class="btn sm" ${comp?'':'disabled aria-disabled="true" title="Lengkapi 3 gambar (Malam, Senja, Siang) dulu"'} onclick="lcSetStatus('${t.id}','active')">${ic('check')}Aktifkan</button>`}
      ${t.isDefault?'':`<button type="button" class="btn sec sm" ${comp?'':'disabled aria-disabled="true"'} onclick="lcSetDefault('${t.id}')">Jadikan default</button>`}
      <button type="button" class="btn ghost sm" onclick="lcArchive('${t.id}')">${ic('trash')}Arsipkan</button>`}
      ${comp||arch?'':'<span class="muted small" style="align-self:center">Belum bisa diaktifkan: wajib 3 gambar.</span>'}</div></div>`}).join('');
  const nArch=LCA.themes.filter(t=>t.status==='archived').length;
  if(nArch)h+=`<div style="margin-top:12px"><button type="button" class="linkbtn" onclick="LCA.showArchived=!LCA.showArchived;lcRenderThemes()">${LCA.showArchived?'Sembunyikan':'Tampilkan'} arsip (${nArch})</button></div>`;
  $('#lcThemes').innerHTML=h;
}
const lcById=id=>LCA.themes.find(t=>t.id===id);
async function lcUpdate(id,patch,okMsg,logMsg){
  if(ROLE!=='admin')return lcDeny();
  const {data,error}=await sb.from('kas_login_theme').update(patch).eq('id',id).select(LG_THEME_COLS).maybeSingle();
  if(error){toast('❌ '+(/th_active_complete|check constraint/i.test(error.message)?'Tema belum lengkap (wajib 3 gambar) atau data tidak valid':error.message));return null}
  if(!data){toast('❌ Perubahan ditolak server (akses admin diperlukan)');return null}
  const i=LCA.themes.findIndex(t=>t.id===id);const nt=lgThemeFromRow(data);if(i>=0)LCA.themes[i]=nt;else LCA.themes.unshift(nt);
  LG.themes=LCA.themes.filter(x=>x.status!=='archived');
  if(logMsg){logAct(logMsg);_saveMsg='';save()}
  if(okMsg)toast(okMsg);lcRenderThemes();return nt;
}
function lcSetStatus(id,st){const t=lcById(id);if(!t)return;
  if(st==='active'&&!LoginCore.canActivate(t))return toast('⚠️ Lengkapi 3 gambar (Malam, Senja, Siang) sebelum mengaktifkan tema');
  const lbl={active:'diaktifkan',inactive:'dinonaktifkan',draft:'dipulihkan sebagai draft'}[st]||st;
  lcUpdate(id,{status:st},'✅ Tema "'+t.name+'" '+lbl,'Tema login "'+t.name+'" '+lbl)}
function lcArchive(id){const t=lcById(id);if(!t)return;
  confirmDanger('Arsipkan tema?','Tema <b>'+esc(t.name)+'</b> tidak akan tampil lagi'+(t.isDefault?' dan status default dilepas (kembali ke tema bawaan)':'')+'. Gambar tetap tersimpan dan tema bisa dipulihkan dari daftar arsip.','Ya, arsipkan',
    ()=>lcUpdate(id,{status:'archived',is_default:false},'🗑️ Tema diarsipkan','Arsipkan tema login "'+t.name+'"'))}
async function lcSetDefault(id){
  if(ROLE!=='admin')return lcDeny();
  const t=id?lcById(id):null;if(id&&!LoginCore.canActivate(t))return toast('⚠️ Tema default wajib punya 3 gambar');
  const {error}=await sb.rpc('kas_set_default_login_theme',{p_id:id});
  if(error)return toast('❌ Gagal set default: '+error.message);
  LCA.themes.forEach(x=>x.isDefault=!!id&&x.id===id);LG.themes=LCA.themes.filter(x=>x.status!=='archived');
  logAct('Tema default login: '+(t?t.name:'bawaan'));_saveMsg='';save();
  toast('✅ Tema default: '+(t?t.name:LOGIN_BUILTIN.name));lcRenderThemes();
}
function lcPreview(id){const t=id==='builtin'?LOGIN_BUILTIN:lcById(id);if(!t)return;const now=LoginCore.timeBucket(new Date());
  modal(`<h3>${ic('eye')}Pratinjau: ${esc(t.name)}</h3><p class="muted small" style="margin:0 0 12px">Potongan ponsel (atas) dan desktop (bawah) per waktu. Bingkai emas = waktu saat ini.</p>
  <div class="pv-grid">${LoginCore.VARIANTS.map(v=>`<div class="pv-cell${v===now?' now':''}"><div class="pv-phone">${t.assets[v]?`<img src="${esc(t.assets[v])}" alt="">`:''}</div><div class="pv-desk">${t.assets[v]?`<img src="${esc(t.assets[v])}" alt="">`:''}</div><b>${esc(LoginCore.VARIANT_LABEL[v])}</b><br><span class="muted small">${esc(LoginCore.VARIANT_HOURS[v])}</span></div>`).join('')}</div>
  <div class="btn-row"><button type="button" class="btn sec" onclick="closeModal()">Tutup</button></div>`)}
/* ----- Editor tema (buat / edit) ----- */
let LCE=null; // {id,files:{night,sunset,day},meta:{}}
function lcSlot(v,t){const url=t&&t.assets[v];return `<div class="th-slot" id="slot-${v}"><b>${esc(LoginCore.VARIANT_LABEL[v])}</b> <span class="muted small">· ${esc(LoginCore.VARIANT_HOURS[v])} WIB</span>
  <figure class="th-thumb" style="margin-top:8px">${url?`<img id="pv-${v}" src="${esc(url)}" alt="Pratinjau ${esc(LoginCore.VARIANT_LABEL[v])}">`:`<span class="ph" id="ph-${v}">Belum ada gambar</span><img id="pv-${v}" alt="Pratinjau ${esc(LoginCore.VARIANT_LABEL[v])}" hidden>`}</figure>
  <label for="f-${v}">${url?'Ganti':'Unggah'} gambar ${esc(LoginCore.VARIANT_LABEL[v])}</label><input type="file" id="f-${v}" accept="image/jpeg,image/png,image/webp" aria-describedby="st-${v}">
  <div class="small" id="st-${v}" aria-live="polite">JPG/PNG/WEBP · maks 5 MB · min 1280×720 · disarankan 16:9</div></div>`}
function lcEdit(id){
  if(ROLE!=='admin')return lcDeny();
  const t=id?lcById(id):null;LCE={id:t?t.id:null,files:{},objUrls:[]};
  modal(`<h3>${ic('image')}${t?'Edit tema':'Tema baru'}</h3>
   <label for="thName">Nama tema</label><input id="thName" maxlength="60" placeholder="mis. HUT RI ke-81" value="${esc(t?t.name:'')}">
   <div class="row2"><div><label for="thPrio">Prioritas (0–100)</label><input id="thPrio" type="number" min="0" max="100" step="1" inputmode="numeric" value="${t?t.priority:10}" aria-describedby="thPrioHelp"><div class="help" id="thPrioHelp">Angka lebih besar menang jika ada tema aktif yang jadwalnya bertabrakan.</div></div><div></div></div>
   <div class="row2"><div><label for="thStart">Mulai tampil (opsional, WIB)</label><input id="thStart" type="datetime-local" value="${t?LoginCore.isoToWibLocal(t.startsAt):''}"></div><div><label for="thEnd">Selesai (opsional, WIB)</label><input id="thEnd" type="datetime-local" value="${t?LoginCore.isoToWibLocal(t.endsAt):''}"></div></div>
   <div class="info">Wajib 3 gambar sebelum tema bisa diaktifkan. Tema yang belum lengkap tersimpan sebagai <b>draft</b>.</div>
   ${LoginCore.VARIANTS.map(v=>lcSlot(v,t)).join('')}
   <div class="msg" id="thMsg" role="alert"></div>
   <div class="btn-row"><button type="button" class="btn" id="thSave">${ic('save')}Simpan</button><button type="button" class="btn ok" id="thSaveAct">${ic('check')}Simpan &amp; Aktifkan</button><button type="button" class="btn sec" onclick="closeModal()">Batal</button></div>`);
  LoginCore.VARIANTS.forEach(v=>{$('#f-'+v).onchange=e=>lcPickFile(v,e.target.files[0])});
  $('#thSave').onclick=()=>lcSaveTheme(false);$('#thSaveAct').onclick=()=>lcSaveTheme(true);lcSyncActBtn();
}
function lcSyncActBtn(){const t=LCE&&LCE.id?lcById(LCE.id):null;const has=v=>!!(LCE.files[v]||(t&&t.paths[v]));const b=$('#thSaveAct');if(!b)return;
  const ok=LoginCore.VARIANTS.every(has);b.disabled=!ok;b.title=ok?'':'Lengkapi 3 gambar dulu'}
function lcImgDims(file){return new Promise(res=>{const u=URL.createObjectURL(file);const im=new Image();im.onload=()=>res({w:im.naturalWidth,h:im.naturalHeight,url:u});im.onerror=()=>res({w:0,h:0,url:u});im.src=u})}
async function lcPickFile(v,file){
  const st=$('#st-'+v);delete LCE.files[v];lcSyncActBtn();if(!file)return;
  const d=await lcImgDims(file);LCE.objUrls.push(d.url);
  const chk=LoginCore.validateImageMeta({type:file.type,size:file.size,width:d.w,height:d.h});
  if(!d.w)chk.errors.push('File gambar tidak bisa dibaca'),chk.ok=false;
  st.className='small '+(chk.ok?'ok':'err');
  st.textContent=chk.ok?('✓ '+d.w+'×'+d.h+' px · '+(file.size/1048576).toFixed(1)+' MB'+(chk.warnings.length?' — '+chk.warnings.join('; '):'')):chk.errors.join(' · ');
  if(!chk.ok){$('#f-'+v).value='';return}
  LCE.files[v]={file,ext:chk.ext};const pv=$('#pv-'+v),ph=$('#ph-'+v);pv.src=d.url;pv.hidden=false;if(ph)ph.remove();lcSyncActBtn();
}
async function lcSaveTheme(activate){
  if(ROLE!=='admin')return lcDeny();
  clearErrs($('#modal'));$('#thMsg').textContent='';
  const name=LoginCore.cleanText($('#thName').value,60);if(!name)return invalid('thName','Nama tema wajib diisi');
  const prio=parseInt($('#thPrio').value,10);if(isNaN(prio)||prio<0||prio>100)return invalid('thPrio','Prioritas 0–100');
  const s=$('#thStart').value?LoginCore.wibLocalToIso($('#thStart').value):null,e=$('#thEnd').value?LoginCore.wibLocalToIso($('#thEnd').value):null;
  if(s&&e&&Date.parse(e)<=Date.parse(s))return invalid('thEnd','Waktu selesai harus setelah waktu mulai');
  const btns=['thSave','thSaveAct'];btns.forEach(i=>$('#'+i).disabled=true);$('#thSave').textContent='Menyimpan…';
  const fail=m=>{$('#thMsg').textContent=m;btns.forEach(i=>$('#'+i).disabled=false);$('#thSave').innerHTML=ic('save')+'Simpan';lcSyncActBtn()};
  try{
    let id=LCE.id,old=id?lcById(id):null;
    if(!id){const {data,error}=await sb.from('kas_login_theme').insert({name,priority:prio,starts_at:s,ends_at:e,status:'draft'}).select('id').single();
      if(error)throw error;id=data.id;LCE.id=id}
    const paths={},uploaded=[];
    for(const v of LoginCore.VARIANTS){const f=LCE.files[v];if(!f)continue;
      const path=`themes/${id}/${v}-${Date.now()}.${f.ext}`;
      const {error}=await sb.storage.from(LOGIN_THEME_BUCKET).upload(path,f.file,{contentType:f.file.type,cacheControl:'31536000',upsert:false});
      if(error)throw new Error('Upload '+LoginCore.VARIANT_LABEL[v]+' gagal: '+error.message);
      paths[v+'_path']=path;uploaded.push(path)}
    const patch={name,priority:prio,starts_at:s,ends_at:e,...paths};
    const merged={night:paths.night_path||(old&&old.paths.night),sunset:paths.sunset_path||(old&&old.paths.sunset),day:paths.day_path||(old&&old.paths.day)};
    const complete=LoginCore.VARIANTS.every(v=>!!merged[v]);
    if(activate){if(!complete)return fail('Tema wajib punya 3 gambar sebelum diaktifkan');patch.status='active'}
    else if(!old)patch.status='draft';
    const nt=await lcUpdate(id,patch,null,null);if(!nt)return fail('Gagal menyimpan tema (lihat pesan di atas)');
    // hapus file lama yang diganti (best-effort)
    const stale=old?LoginCore.VARIANTS.filter(v=>paths[v+'_path']&&old.paths[v]).map(v=>old.paths[v]):[];
    if(stale.length)sb.storage.from(LOGIN_THEME_BUCKET).remove(stale).then(({error})=>error&&console.warn('Hapus file lama gagal',error.message));
    logAct((old?'Ubah':'Buat')+' tema login "'+name+'"'+(activate?' & aktifkan':'')+(uploaded.length?' ('+uploaded.length+' gambar)':''));_saveMsg='Tema login';save();
    LCE.objUrls.forEach(u=>URL.revokeObjectURL(u));closeModal();
    toast('✅ Tema "'+name+'" '+(activate?'disimpan & aktif':complete?'disimpan':'disimpan sebagai draft'));lcRenderThemes();
  }catch(err){console.error(err);fail('❌ '+(err.message||err));if(LCE.id&&!lcById(LCE.id))lcLoad(true)}
}
$('#thNew').onclick=()=>lcEdit(null);
$('#lcReload').onclick=()=>{LCA.remTouched=false;lcLoad(true)};
